import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.sql.*;
import javax.naming.*;
import javax.sql.DataSource;
import org.apache.commons.text.StringSubstitutor;
import org.apache.commons.text.lookup.StringLookupFactory;

@WebServlet("/api/notifications")
public class NotificationServlet extends HttpServlet {

    private DataSource dataSource;

    @Override
    public void init() throws ServletException {
        try {
            Context ctx = new InitialContext();
            dataSource = (DataSource) ctx.lookup("java:comp/env/jdbc/notifyDB");
        } catch (NamingException e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String templateName = req.getParameter("template");
        String recipientName = req.getParameter("name");
        String recipientEmail = req.getParameter("email");
        String customMessage = req.getParameter("message");

        if (templateName == null || recipientName == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        try {
            String template = loadTemplate(templateName);

            // Build substitution map from user inputs
            Map<String, String> valueMap = new HashMap<>();
            valueMap.put("name", recipientName);
            valueMap.put("email", recipientEmail != null ? recipientEmail : "");
            valueMap.put("message", customMessage != null ? customMessage : "");
            valueMap.put("date", new java.text.SimpleDateFormat("yyyy-MM-dd").format(new Date()));

            // Perform template interpolation using Commons Text
            StringSubstitutor substitutor = new StringSubstitutor(
                StringLookupFactory.INSTANCE.interpolatorStringLookup(valueMap)
            );
            substitutor.setEnableSubstitutionInVariables(true);
            String rendered = substitutor.replace(template);

            // Log the notification
            logNotification(recipientEmail, templateName, rendered);

            resp.setContentType("text/html; charset=UTF-8");
            resp.getWriter().write(rendered);

        } catch (Exception e) {
            resp.sendError(500, "Template rendering failed: " + e.getMessage());
        }
    }

    private String loadTemplate(String name) throws IOException {
        // Sanitize template name to prevent path traversal
        String safeName = name.replaceAll("[^a-zA-Z0-9_-]", "");
        InputStream is = getServletContext().getResourceAsStream(
            "/WEB-INF/templates/" + safeName + ".txt"
        );
        if (is == null) {
            return "Hello ${name}, ${message}";
        }
        try (BufferedReader br = new BufferedReader(new InputStreamReader(is))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line).append("\n");
            }
            return sb.toString();
        }
    }

    private void logNotification(String email, String template, String content) {
        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "INSERT INTO notification_log (recipient, template_name, sent_at) VALUES (?, ?, NOW())")) {
            ps.setString(1, email);
            ps.setString(2, template);
            ps.executeUpdate();
        } catch (SQLException e) {
            getServletContext().log("Failed to log notification", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Preview endpoint - renders template with sample data
        String templateName = req.getParameter("template");
        if (templateName == null) {
            resp.sendError(400, "Missing template parameter");
            return;
        }
        String template = loadTemplate(templateName);
        Map<String, String> sampleMap = new HashMap<>();
        sampleMap.put("name", "John Doe");
        sampleMap.put("email", "john@example.com");
        sampleMap.put("message", "This is a preview.");
        sampleMap.put("date", "2024-01-01");

        StringSubstitutor sub = new StringSubstitutor(
            StringLookupFactory.INSTANCE.interpolatorStringLookup(sampleMap)
        );
        sub.setEnableSubstitutionInVariables(true);
        resp.setContentType("text/plain; charset=UTF-8");
        resp.getWriter().write(sub.replace(template));
    }
}
